// Generated with the ARB keys for «أدوات القعدة»: code -> (name, description).
import '../../app/l10n/app_localizations.dart';

(String, String)? tableToolCopy(AppLocalizations l, String code) =>
    switch (code) {
      'extra_minute' => (l.toolExtraMinuteName, l.toolExtraMinuteDesc),
      'anon_note' => (l.toolAnonNoteName, l.toolAnonNoteDesc),
      'last_will' => (l.toolLastWillName, l.toolLastWillDesc),
      'spotlight' => (l.toolSpotlightName, l.toolSpotlightDesc),
      'objection' => (l.toolObjectionName, l.toolObjectionDesc),
      'last_word' => (l.toolLastWordName, l.toolLastWordDesc),
      'vote_shield' => (l.toolVoteShieldName, l.toolVoteShieldDesc),
      'half_door' => (l.toolHalfDoorName, l.toolHalfDoorDesc),
      'double_vote' => (l.toolDoubleVoteName, l.toolDoubleVoteDesc),
      'camouflage' => (l.toolCamouflageName, l.toolCamouflageDesc),
      'revote' => (l.toolRevoteName, l.toolRevoteDesc),
      'grave_vote' => (l.toolGraveVoteName, l.toolGraveVoteDesc),
      'sense' => (l.toolSenseName, l.toolSenseDesc),
      'impersonate' => (l.toolImpersonateName, l.toolImpersonateDesc),
      'narrator_whisper' => (
        l.toolNarratorWhisperName,
        l.toolNarratorWhisperDesc,
      ),
      'lock_door' => (l.toolLockDoorName, l.toolLockDoorDesc),
      'appeal' => (l.toolAppealName, l.toolAppealDesc),
      _ => null,
    };
